CREATE TABLE orders (
  id INTEGER PRIMARY KEY, number TEXT NOT NULL, type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ciorna',
  company_id INTEGER NOT NULL, point_id INTEGER NOT NULL, dest_point_id INTEGER, partner_id INTEGER, partner_point_id INTEGER,
  order_date TEXT NOT NULL, planned_date TEXT, unload_date TEXT, incoterm TEXT, currency TEXT DEFAULT 'RON', extern INTEGER DEFAULT 0,
  payment TEXT, transport_mode TEXT DEFAULT 'nestabilit', carrier_id INTEGER, vehicle_id INTEGER, driver_id INTEGER, notes TEXT,
  created TEXT, created_by TEXT, updated TEXT, approved_at TEXT, approved_by TEXT
);
CREATE UNIQUE INDEX orders_number ON orders (number);
CREATE TABLE order_lines (
  id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), article_id INTEGER NOT NULL, ewc_id INTEGER,
  qty REAL, um TEXT, price REAL, notes TEXT, UNIQUE (order_id, article_id)
);
CREATE TABLE order_status (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL, from_status TEXT, to_status TEXT NOT NULL, ts TEXT NOT NULL, user_name TEXT, reason TEXT);
CREATE TABLE order_files (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL, kind TEXT NOT NULL, file_id TEXT NOT NULL, name TEXT, ts TEXT, user_name TEXT);
